package com.mall.controller.user;
import com.mall.common.result.Result; import com.mall.service.PrivacyService; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.Map;
@RestController @RequestMapping("/api/privacy") public class PrivacyController { private final PrivacyService service; public PrivacyController(PrivacyService service){this.service=service;} @GetMapping("/export") public Result<Map<String,Object>> export(@AuthenticationPrincipal Long userId){return Result.success(service.exportPersonalData(userId));} @DeleteMapping("/account") public Result<Void> close(@AuthenticationPrincipal Long userId){service.closeAccount(userId);return Result.success("账户已注销",null);} @GetMapping("/documents") public Result<Map<String,String>> documents(){return Result.success(Map.of("privacyPolicy","平台仅在提供订单、配送、售后与账户服务所必需的范围内处理个人信息。","userAgreement","用户应妥善保管账户凭证，不得利用平台进行违法违规交易。"));} }
